/** Real host/plugin boundary + live reads + isolated downloads. No real progress writes or posts. */
public final class HostPluginInstrumentation extends Instrumentation {
    JSONArray checks=new JSONArray(),failures=new JSONArray();FanqieActivity activity;volatile String stage="start";
    void check(String name,boolean ok){if(!ok)throw new AssertionError(name);checks.put(name);Bundle b=new Bundle();b.putString("check",name);sendStatus(1,b);}
    void main(Runnable r){runOnMainSync(r);waitForIdleSync();}
    <T extends View>T find(View root,Class<T> type,String label){if(type.isInstance(root)&&(label==null||(root instanceof TextView&&((TextView)root).getText().toString().equals(label))))return type.cast(root);if(root instanceof ViewGroup){ViewGroup g=(ViewGroup)root;for(int i=0;i<g.getChildCount();i++){T v=find(g.getChildAt(i),type,label);if(v!=null)return v;}}return null;}
    View decor(){return activity.getWindow().getDecorView();}
    ReaderView reader(){return find(decor(),ReaderView.class,null);}
    void await(BooleanSupplier ready)throws Exception{long end=System.currentTimeMillis()+45000;while(System.currentTimeMillis()<end){boolean[] ok={false};main(()->ok[0]=ready.getAsBoolean());if(ok[0])return;Thread.sleep(150);}throw new IOException("UI timeout at "+stage);}
    void button(String text)throws Exception{await(()->find(decor(),Button.class,text)!=null);}
    void click(String text){main(()->{Button b=find(decor(),Button.class,text);if(b==null)throw new AssertionError("Missing button "+text);b.performClick();});}
    void set(String field,Object value){try{Field f=FanqieActivity.class.getDeclaredField(field);f.setAccessible(true);f.set(activity,value);}catch(Exception e){throw new RuntimeException(e);}}
    void flip(boolean next){main(()->{ReaderView view=reader();long t=SystemClock.uptimeMillis();float x=view.getWidth()*(next?.8f:.2f),y=view.getHeight()/2f;MotionEvent a=MotionEvent.obtain(t,t,0,x,y,0),b=MotionEvent.obtain(t,t+20,1,x,y,0);view.dispatchTouchEvent(a);view.dispatchTouchEvent(b);a.recycle();b.recycle();});}
    void shot(String name)throws Exception{android.graphics.Bitmap b=getUiAutomation().takeScreenshot();if(b!=null)try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name+".png"))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}}
    @Override public void onCreate(Bundle b){super.onCreate(b);start();}
    @Override public void onStart(){java.util.concurrent.ScheduledExecutorService watchdog=java.util.concurrent.Executors.newSingleThreadScheduledExecutor();watchdog.schedule(()->{Bundle b=new Bundle();b.putString("timeout",stage);finish(0,b);},240,java.util.concurrent.TimeUnit.SECONDS);try{
        Context ctx=getTargetContext();activity=(FanqieActivity)startActivitySync(new Intent(ctx,FanqieActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("progress_test_readonly",true));
        stage="trust-and-connection";button("书架分类");check("ui-runs-inside-main-program",activity.getPackageName().equals(PluginTrust.HOST));check("mutual-installed-signatures-match",PluginTrust.host(ctx)&&PluginTrust.plugin(ctx));RemotePluginClient source=new RemotePluginClient(ctx);source.refresh();check("existing-encrypted-plugin-account-survives-upgrade",source.loggedIn()&&source.accountScope().matches("[0-9a-f]{24}"));try{ctx.getClassLoader().loadClass("com.watchreader.fanqie.DesktopSigner");throw new AssertionError("Host contains signer");}catch(ClassNotFoundException expected){check("host-has-no-downloader-signer",true);}try{ctx.getClassLoader().loadClass("com.watchreader.fanqie.CredentialStore");throw new AssertionError("Host contains credential store");}catch(ClassNotFoundException expected){check("host-has-no-cookie-storage-code",true);}
        stage="live-provider-data";List<ShelfGroup> groups=source.shelfGroups();Page<BookInfo> shelf=source.bookshelf("");check("remote-shelf-groups-and-metadata",groups.size()>2&&!shelf.items.isEmpty()&&!shelf.items.get(0).title.equals(shelf.items.get(0).id));Page<BookInfo> more=source.bookshelf(shelf.next);check("remote-shelf-pagination",!more.items.isEmpty()&&!more.items.get(0).id.equals(shelf.items.get(0).id));check("remote-search",!source.search("鲁迅","").items.isEmpty());BookInfo book=new BookInfo("7134994653631220774","主程序联动测试","");BookDetails detail=source.details(book);check("remote-details-and-cover-url",detail.chapters>0&&!detail.description.isEmpty()&&detail.coverUrl.startsWith("https://"));List<ChapterInfo> directory=source.directory(book.id);ChapterContent chapter=source.chapter(book.id,directory.get(0));check("streamed-directory-and-decrypted-chapter",directory.size()>100&&chapter.paragraphs.size()>20);Page<Comment> comments=source.comments(chapter,chapter.paragraphs.get(0),"");check("remote-paragraph-comments",!comments.items.isEmpty());ReadingProgress cloud=source.readProgress(book.id);check("remote-cloud-progress-read-only",cloud!=null&&cloud.chapter>0);
        stage="host-ui";button("书架分类");BookInfo first=shelf.items.get(0);String label=first.title+(first.author.isEmpty()?"":"\n"+first.author);button(label);click(label);button("下载到本地");check("host-book-menu-has-download-and-details",find(decor(),Button.class,"查看详情")!=null&&find(decor(),Button.class,"查看封面")!=null);shot("host-plugin-menu");main(()->activity.bookDetails(book));button("返回书籍菜单");check("host-displays-remote-details",find(decor(),TextView.class,detail.description)!=null);main(()->activity.bookCover(book));await(()->find(decor(),ImageView.class,null)!=null);check("host-displays-cover",true);shot("host-plugin-cover");
        stage="host-cloud-reader";main(()->activity.openBook(book));int target=0;for(int i=0;i<directory.size();i++)if(directory.get(i).id.equals(cloud.itemId)){target=i;break;}String resume="继续阅读 · "+(target+1);button(resume);click(resume);await(()->reader()!=null&&activity.current.itemId.equals(cloud.itemId)&&reader().getWidth()>0&&reader().getCharOffset()==ChapterPosition.offset(activity.current,cloud));check("host-reader-restores-cloud-paragraph",reader().getCharOffset()==ChapterPosition.offset(activity.current,cloud));check("host-uses-shared-full-size-reader",reader().getClass()==ReaderView.class&&reader().getWidth()==466&&reader().getHeight()==466);await(()->reader().isPageCountExact());check("host-reader-count-is-bounded",reader().getPageIndex()+1<=reader().getPageCount());
        stage="host-continuous-reader";Fake fake=new Fake();main(()->{activity.plugin=fake;set("bookId","99123");set("chapters",fake.chapters);set("chapterIndex",0);set("entryOffset",Integer.valueOf(0));activity.current=fake.content("99123",0);activity.showReader();});await(()->reader()!=null&&reader().getWidth()>0&&activity.current.itemId.equals("991230"));main(()->reader().restoreToEnd());int endOffset=reader().getCharOffset();check("shared-final-page-has-accurate-total",reader().isPageCountExact()&&reader().getPageIndex()+1==reader().getPageCount());Thread.sleep(150);flip(true);await(()->reader()!=null&&reader().getWidth()>0&&activity.current.itemId.equals("991231"));check("host-auto-next-chapter",reader().getCharOffset()==0);Thread.sleep(150);flip(false);await(()->reader()!=null&&reader().getWidth()>0&&activity.current.itemId.equals("991230"));check("host-auto-previous-final-page",reader().getCharOffset()==endOffset);
        stage="resumable-local-download";File fixture=new File(ctx.getFilesDir(),"integration-download-"+System.currentTimeMillis()),books=new File(fixture,"books"),work=new File(fixture,"work");BookInfo testBook=new BookInfo("99123","离线下载测试","");AtomicBoolean pause=new AtomicBoolean();Fake downloadSource=new Fake();LocalBookDownloader engine=new LocalBookDownloader(books,work,1);File stopped=engine.download("test-scope",testBook,downloadSource.chapters,downloadSource,pause::get,(done,total)->{if(done==1)pause.set(true);});check("pause-saves-one-chapter-checkpoint",stopped==null&&downloadSource.calls==1);check("incomplete-download-not-in-local-library",books.listFiles().length==0);File partial=work.listFiles((d,n)->n.endsWith(".part"))[0];try(FileOutputStream append=new FileOutputStream(partial,true)){append.write("未提交的尾部".getBytes(StandardCharsets.UTF_8));}pause.set(false);File complete=new LocalBookDownloader(books,work,1).download("test-scope",testBook,downloadSource.chapters,downloadSource,()->false,(done,total)->{});String text=new String(java.nio.file.Files.readAllBytes(complete.toPath()),StandardCharsets.UTF_8);check("resume-fetches-only-remaining-chapters",downloadSource.calls==3);check("resume-removes-uncommitted-tail",!text.contains("未提交的尾部"));check("completed-txt-contains-every-chapter-once",complete.getName().endsWith(".txt")&&text.contains("第一章 开始")&&text.indexOf("第一章 开始")==text.lastIndexOf("第一章 开始")&&text.contains("第二章 中段")&&text.contains("第三章 结尾"));check("completed-download-has-no-partial-files",work.listFiles().length==0);
        stage="offline-shared-reader";int calls=downloadSource.calls;Activity offline=startActivitySync(new Intent(ctx,com.watchreader.ReaderActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra(com.watchreader.ReaderActivity.EXTRA_PATH,complete.getAbsolutePath()));long until=System.currentTimeMillis()+15000;while(System.currentTimeMillis()<until){ReaderView r=find(offline.getWindow().getDecorView(),ReaderView.class,null);if(r!=null&&r.getCharCount()>0)break;Thread.sleep(150);}check("downloaded-book-opens-in-main-local-reader",find(offline.getWindow().getDecorView(),ReaderView.class,null).getCharCount()>0);check("offline-reader-does-not-call-plugin",downloadSource.calls==calls);main(offline::finish);
        stage="read-only-live-chapter-download";File liveRoot=new File(fixture,"live"),liveBooks=new File(liveRoot,"books");File liveFile=new LocalBookDownloader(liveBooks,new File(liveRoot,"work")).download("test-live",book,Collections.singletonList(directory.get(0)),source,()->false,(done,total)->{});check("real-chapter-download-produces-readable-txt",liveFile.isFile()&&new String(java.nio.file.Files.readAllBytes(liveFile.toPath()),StandardCharsets.UTF_8).contains(chapter.paragraphs.get(0).text));
        stage="download-ui";BookInfo uiBook=new BookInfo("9912349","联动下载自动化测试","");main(()->{activity.plugin=new Fake();activity.bookActions(uiBook);});click("下载到本地");button("开始 / 继续下载");click("开始 / 继续下载");button("离线阅读");File uiFile=new File(ctx.getFilesDir(),"books/联动下载自动化测试_9912349.txt");check("download-button-publishes-completed-book-to-main-library",uiFile.isFile()&&uiFile.length()>0);shot("host-download-complete");
        stage="restore-main-shelf";main(()->{activity.plugin=source;activity.home();});button("书架分类");
    }catch(Throwable e){failures.put(stage+": "+e.getClass().getSimpleName()+" "+e.getMessage());}finally{watchdog.shutdownNow();try{JSONObject report=new JSONObject().put("checks",checks).put("failures",failures).put("real_public_posts",0).put("real_cloud_test_position_writes",0);try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),"host-plugin-report.json"))){out.write(report.toString(2).getBytes(StandardCharsets.UTF_8));}Bundle result=new Bundle();result.putString("summary","host/plugin checks="+checks.length()+" failures="+failures.length());result.putString("failures",failures.toString());finish(failures.length()==0?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}catch(Exception ignored){finish(0,new Bundle());}}}
    static final class Fake implements ReaderPlugin {
        List<ChapterInfo> chapters=Arrays.asList(new ChapterInfo("991230","第一章 开始","v"),new ChapterInfo("991231","第二章 中段","v"),new ChapterInfo("991232","第三章 结尾","v"));int calls;
        ChapterContent content(String book,int n){List<Paragraph> paras=new ArrayList<>();for(int i=0;i<30;i++)paras.add(new Paragraph(i,"离线阅读与主程序联动测试正文，段落序号"+i+"；不向真实账号写入进度。"));return new ChapterContent(book,chapters.get(n).id,chapters.get(n).title,"v",paras);}
        public String id(){return "test";}public Page<BookInfo> bookshelf(String c){return new Page<>(Collections.emptyList(),"",false);}public Page<BookInfo> search(String q,String c){return bookshelf(c);}public List<ChapterInfo> directory(String book){return chapters;}public ChapterContent chapter(String book,ChapterInfo c){calls++;return content(book,chapters.indexOf(c));}public Page<Comment> comments(ChapterContent c,Paragraph p,String cursor){return new Page<>(Collections.emptyList(),"",false);}public String publish(ChapterContent c,Paragraph p,String text){throw new AssertionError("No public test posts");}
    }
}
